select p.dept_name yname, d.dept_name dname, u.login_name, u.user_name username, s.reward_name, s.jifen, s.reward_leixing, s.state, s.reward_time from sys_reward s left join sys_user u on s.user_id = u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id = p.dept_id where 1=1
AND p.dept_id = #{college}
AND d.dept_id = #{major}
AND u.user_id = #{teacherName}
and s.reward_time >= #{startTime}
and s.reward_time <= #{endTime}
and s.reward_name like concat('%', #{topicName}, '%')
AND s.state in (3,5,7,11)
AND s.state in (1,2,4)
AND s.state in (6)
