${_dataScope}
order by yname asc,dname asc,u.login_name asc

SELECT s.id, s.user_id, s.reward_name, s.reward_danwei, s.reward_leixing, s.reward_wenjian, s.reward_time, s.reward_fenlei, s.reward_dengji, s.reward_paiming, s.reward_jibie, s.jifen, s.expected_jifen, s.state, s.first_person_id, s.second_person_id, s.third_person_id, s.fourth_person_id, s.extra_member_ids, s.expected_score1, s.expected_score2, s.expected_score3, s.expected_score4, s.extra_member_scores, u.user_name username, d.dept_name dname, p.dept_name yname, rp.ranking as personal_ranking, rp.expected_score as personal_expected_score, rp.actual_score as personal_actual_score FROM sci_reward_persion rp LEFT JOIN sys_reward s ON rp.reward_id = s.id LEFT JOIN sys_user u ON s.user_id = u.user_id LEFT JOIN sys_dept d ON u.dept_id = d.dept_id LEFT JOIN sys_dept p ON d.parent_id = p.dept_id WHERE rp.persion_id = #{persionId}
and YEAR(DATE_ADD(s.reward_time, INTERVAL 1 MONTH)) = #{year}
ORDER BY s.reward_time DESC
